        "component_id": "comp_power_supply",
        "name": "Power Supply",
        "description": "The power supply assembly whose cover and component barrier are replaced.",
        "category": "power system"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power Supply Cover",
        "description": "The cover fitted over the power supply, aligned with the panels and tracks.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_panel",
        "name": "Panel",
        "description": "The front and rear panels aligned with the power supply during cover and barrier replacement.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_handle",
        "name": "Handle",
        "description": "The handle attached at the top of the power supply cover.",
        "category": "structural"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan positioned behind the largest louvers in the power supply cover.",
        "category": "cooling"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component Barrier",
        "description": "A flexible barrier removed from the power board side of the power supply and installed to cover the top of the power board.",
        "category": "electrical protection"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power Board",
        "description": "The board covered at its top by the component barrier.",
        "category": "electrical"
      },
      {
        "component_id": "comp_plastic_base",
        "name": "Plastic Base",
        "description": "The base with inside notches that retain the bottom edge of the component barrier.",
        "category": "structural"
      },
      {
        "component_id": "comp_ground_clip",
        "name": "Ground Clip",
        "description": "The clip whose hole is aligned with the screw holes in the rear panel and power supply during cover installation.",
